            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionPool.Predict(input);

        // Read label names from the saved model's schema
        var mlContext = new MLContext();
        var model = mlContext.Model.Load(_modelPath, out _);
        var labelBuffer = new VBuffer<ReadOnlyMemory<char>>();
        model.GetOutputSchema(SchemaBuilder.Create().ToSchema())
            .GetColumn("Score").GetSlotNames(ref labelBuffer);

