using Microsoft.ML;
using Microsoft.ML.Data;

namespace TicketClassifier.Services;

/// <summary>
/// Caches the label names from the trained model so they are loaded once at startup.
/// </summary>
public class LabelService
{
    public string[] LabelNames { get; }

    public LabelService(IWebHostEnvironment env)
    {
        var modelPath = Path.Combine(env.ContentRootPath, "Data", "model.zip");
        var mlContext = new MLContext();
        var model = mlContext.Model.Load(modelPath, out var schema);

        var labelBuffer = new VBuffer<ReadOnlyMemory<char>>();
        var outputSchema = model.GetOutputSchema(schema);
        var scoreColumn = outputSchema["Score"];
        scoreColumn.GetSlotNames(ref labelBuffer);
        LabelNames = labelBuffer.DenseValues().Select(v => v.ToString()).ToArray();
    }
}

